"""Parse the summary comments Snapmaker Orca writes into a G-code file.

A sliced file (verified on Snapmaker Orca 01.10.01.50) contains:

    ; HEADER_BLOCK_START
    ; generated by Snapmaker Orca 2.4.0 on 2026-10-28 at 11:57:28
    ; total layer number: 100
    ; max_z_height: 20.05
    ; HEADER_BLOCK_END
    ...
    ; EXECUTABLE_BLOCK_END
    ; filament used [g] = 3.65, 0.00, 0.00, 0.00
    ; total filament used [g] = 3.65
    ; estimated printing time (normal mode) = 15m 1s
    ; CONFIG_BLOCK_START
    ; layer_height = 0.2
    ...
    ; CONFIG_BLOCK_END

All numbers in `SliceResult` come from these lines; nothing is estimated here.
"""

from __future__ import annotations

import os
import re
from dataclasses import dataclass, field
from pathlib import Path

from print_copilot.errors import GcodeParseError

# Settings from the config block that are copied into `SliceResult.settings`.
KEY_SETTINGS: tuple[str, ...] = (
    "printer_model",
    "printer_settings_id",
    "print_settings_id",
    "filament_settings_id",
    "filament_type",
    "nozzle_diameter",
    "layer_height",
    "initial_layer_print_height",
    "wall_loops",
    "top_shell_layers",
    "bottom_shell_layers",
    "sparse_infill_density",
    "sparse_infill_pattern",
    "enable_support",
    "support_type",
    "enable_prime_tower",
    "curr_bed_type",
)

_DURATION_PART = re.compile(r"(\d+)\s*([dhms])")
_DURATION_UNITS_S = {"d": 86400, "h": 3600, "m": 60, "s": 1}


def parse_duration_s(text: str) -> int:
    """Convert a slicer duration such as `1d 2h 3m 4s` or `19s` to seconds."""
    text = text.strip()
    parts = _DURATION_PART.findall(text)
    if not parts or _DURATION_PART.sub("", text).strip():
        raise GcodeParseError(f"Unrecognised duration {text!r}")
    return sum(int(value) * _DURATION_UNITS_S[unit] for value, unit in parts)


def _floats(text: str) -> list[float]:
    try:
        return [float(v) for v in text.split(",") if v.strip()]
    except ValueError as exc:
        raise GcodeParseError(f"Expected a comma-separated number list, got {text!r}") from exc


def _unquote(value: str) -> str:
    value = value.strip()
    # Lists such as `"Generic PLA";"Generic PLA"` keep their quotes.
    if len(value) >= 2 and value[0] == value[-1] == '"' and '"' not in value[1:-1]:
        return value[1:-1]
    return value


@dataclass
class SliceResult:
    """Measured numbers from one sliced plate. Index i of a list is tool head T<i>."""

    generator: str | None
    estimated_time_s: int
    first_layer_time_s: int | None
    layer_count: int
    max_z_height_mm: float | None
    filament_used_g: list[float]
    filament_used_mm: list[float]
    filament_used_cm3: list[float]
    total_filament_g: float
    filament_cost: list[float]
    total_filament_cost: float | None
    settings: dict[str, str] = field(default_factory=dict)

    @property
    def tool_count(self) -> int:
        return len(self.filament_used_g)

    @property
    def tools_used(self) -> list[int]:
        """Indexes of tool heads that extrude any filament."""
        return [i for i, grams in enumerate(self.filament_used_g) if grams > 0]

    @property
    def printer_settings_id(self) -> str | None:
        return self.settings.get("printer_settings_id")

    @property
    def print_settings_id(self) -> str | None:
        return self.settings.get("print_settings_id")


def parse_gcode_text(lines: list[str] | str) -> SliceResult:
    """Parse G-code text (or its lines). Only comment lines are inspected."""
    if isinstance(lines, str):
        lines = lines.splitlines()

    summary: dict[str, str] = {}
    config: dict[str, str] = {}
    generator = None
    in_config = False
    for raw in lines:
        if not raw.startswith(";"):
            continue
        line = raw[1:].strip()
        if line == "CONFIG_BLOCK_START":
            in_config = True
            continue
        if line == "CONFIG_BLOCK_END":
            in_config = False
            continue
        if line.startswith("generated by "):
            generator = line[len("generated by ") :].split(" on ")[0].strip()
            continue
        if in_config:
            key, sep, value = line.partition(" = ")
            if sep:
                config[key.strip()] = value
            continue
        for separator in (" = ", ": "):
            key, sep, value = line.partition(separator)
            if sep:
                summary.setdefault(key.strip(), value.strip())
                break

    def required(key: str) -> str:
        if key not in summary:
            raise GcodeParseError(
                f"G-code has no '; {key}' line; the slice is incomplete or the "
                "Snapmaker Orca output format changed."
            )
        return summary[key]

    estimated_time_s = parse_duration_s(required("estimated printing time (normal mode)"))
    filament_g = _floats(required("filament used [g]"))
    total_g = float(required("total filament used [g]"))

    layer_text = summary.get("total layers count") or required("total layer number")
    first_layer = summary.get("estimated first layer printing time (normal mode)")
    max_z = summary.get("max_z_height")
    cost_total = summary.get("total filament cost")

    if abs(sum(filament_g) - total_g) > 0.02 * max(len(filament_g), 1):
        raise GcodeParseError(
            f"Per-tool filament grams {filament_g} do not add up to the total {total_g} g."
        )

    return SliceResult(
        generator=generator,
        estimated_time_s=estimated_time_s,
        first_layer_time_s=parse_duration_s(first_layer) if first_layer else None,
        layer_count=int(layer_text),
        max_z_height_mm=float(max_z) if max_z else None,
        filament_used_g=filament_g,
        filament_used_mm=_floats(summary.get("filament used [mm]", "")),
        filament_used_cm3=_floats(summary.get("filament used [cm3]", "")),
        total_filament_g=total_g,
        filament_cost=_floats(summary.get("filament cost", "")),
        total_filament_cost=float(cost_total) if cost_total else None,
        settings={k: _unquote(config[k]) for k in KEY_SETTINGS if k in config},
    )


def parse_gcode(path: str | os.PathLike[str]) -> SliceResult:
    """Parse a G-code file written by Snapmaker Orca."""
    gcode_path = Path(path)
    try:
        with gcode_path.open(encoding="utf-8", errors="replace") as handle:
            comments = [line for line in handle if line.startswith(";")]
    except OSError as exc:
        raise GcodeParseError(f"Cannot read G-code {gcode_path}: {exc}") from exc
    try:
        return parse_gcode_text(comments)
    except GcodeParseError as exc:
        raise GcodeParseError(f"{gcode_path}: {exc}") from exc
